import './Veiculo.css';
import carros from './carros'; // Confirme se o nome do arquivo é carros.js ou dados.js
import { useParams } from 'react-router-dom';

function Veiculo() { // Removi o 'props' daqui, pois não é usado
    const { id } = useParams();

    // Essa lógica está perfeita!
    const carro = carros.find((item) => item.id === parseInt(id));

    if (!carro) {
        return <h2>Carro não encontrado!</h2>;
    }

    return(
        <div className="col"> 
            <div className="card shadow-sm"> 
                {/* CORREÇÃO 1: O nome no banco de dados é 'imagem', não 'img' */}
                <img
                    src={carro.imagem} 
                    className="bd-placeholder-img card-img-top" 
                    alt={carro.titulo} // CORREÇÃO 2: Use carro.titulo
                    width="100%" 
                    height="300"
                    style={{objectFit: "cover"}} // Dica: Adicionei isso para a foto não distorcer
                />    
                <div className="card-body">                

                    {/* CORREÇÃO 3: Use carro.titulo e carro.preco em vez de props */}
                    <p className="propriedades-veiculo"><b>{carro.titulo}</b></p> 
                    <p className="propriedades-veiculo"><b>R$ {carro.preco}</b></p>

                </div> 
            </div> 
        </div>
    );
}

export default Veiculo;
